static int ref_eq(ZnRef a,ZnRef b) {
    return a.slot==b.slot && a.tensor==b.tensor && a.generation==b.generation;
}
static int event_eq(const ZnEvent *a,const ZnEvent *b) {
    unsigned i;
    if(a->event!=b->event || a->tile_first!=b->tile_first ||
       a->tile_count!=b->tile_count || a->compute_node!=b->compute_node ||
       a->operation!=b->operation || a->read_count!=b->read_count ||
       a->retire_count!=b->retire_count || a->has_destination!=b->has_destination)
        return 0;
    if(a->has_destination &&
       (a->destination.address!=b->destination.address ||
        a->destination.bytes!=b->destination.bytes ||
        a->destination.channels!=b->destination.channels ||
        a->destination.height!=b->destination.height ||
        a->destination.width!=b->destination.width ||
        !ref_eq(a->destination.ref,b->destination.ref))) return 0;
    for(i=0;i<a->read_count;i++) if(!ref_eq(a->reads[i],b->reads[i])) return 0;
    for(i=0;i<a->retire_count;i++) if(!ref_eq(a->retired[i],b->retired[i])) return 0;
    return 1;
}

static int span(const void *p,size_t n) {return p && n && n<=UINTPTR_MAX-(uintptr_t)p;}
static int overlap(const void *a,size_t n,const void *b,size_t m) {
    uintptr_t x=(uintptr_t)a,y=(uintptr_t)b;return x<y+m && y<x+n;
}
static size_t packed_bytes(unsigned c,unsigned h,unsigned w) {
    return (size_t)((c+3u)/4u)*h*((w+15u)/16u)*64u;
}
static size_t offset(unsigned channels,unsigned h,unsigned w,unsigned c,unsigned y,unsigned x) {
    size_t xwords=(w+15u)/16u,g32=c/32u*32u,groups=((channels-g32<32u?channels-g32:32u)+3u)/4u;
    return ((g32/4u)*h*xwords+(y*xwords+x/16u)*groups+(c%32u)/4u)*64u+(c%4u)*16u+x%16u;
}
/* Raw sampler for fused Add tables; unary transforms are already in table. */
static uint8_t sample_raw(const Operand *op,const ZnNativeViewSourceV1 *s,unsigned c,unsigned y,unsigned x) {
    const Map *m=&maps[op->first+c];const ZnNativeViewSourceV1 *v=&s[m->source];
    return v->data[offset(v->channels,v->height,v->width,m->channel,y/m->dh,x/m->dw)];
}
static uint8_t sample(const Operand *op,const ZnNativeViewSourceV1 *s,unsigned c,unsigned y,unsigned x) {
    const Map *m=&maps[op->first+c];const ZnNativeViewSourceV1 *v=&s[m->source];
    uint8_t raw=v->data[offset(v->channels,v->height,v->width,m->channel,y/m->dh,x/m->dw)];
    return unary[(size_t)m->lut*256u+(raw^128u)];
}
const ZnEvent *zn_native_nonconv_event_v1(uint16_t index) {
    return index<73?&z100_graph_events[index]:(const ZnEvent *)0;
}
int zn_native_nonconv_run_v1(const ZnRequest *r,const ZnNativeViewSourceV1 *s,
                           uint8_t count,uint8_t *out,size_t bytes) {
    const ZnEvent *e;const Job *j;const Operand *op;unsigned i,c,y,x;size_t cursor=0;
    if(!r || !r->job || !r->epoch || !r->tag || r->operation!=ZN_RUN || r->event_index>=73) return -1;
    e=&z100_graph_events[r->event_index];j=&jobs[r->event_index];
    if(!event_eq(e,r->job)) return -1;
    if(!j->mode) return 1;
    if(!s || count!=e->read_count || !count || count>7 || bytes!=j->bytes || !span(out,bytes) ||
       !span(s,(size_t)count*sizeof *s) || overlap(out,bytes,s,(size_t)count*sizeof *s) ||
       overlap(out,bytes,r,sizeof *r) || overlap(out,bytes,r->job,sizeof *r->job) ||
       overlap(out,bytes,jobs,sizeof jobs) || overlap(out,bytes,operands,sizeof operands) ||
       overlap(out,bytes,maps,sizeof maps) || overlap(out,bytes,unary,sizeof unary) ||
       overlap(out,bytes,operation_tables,sizeof operation_tables)) return -1;
    for(i=0;i<count;i++) if(s[i].epoch!=r->epoch || !ref_eq(s[i].ref,e->reads[i]) ||
       s[i].channels!=j->sc[i] || s[i].height!=j->sh[i] || s[i].width!=j->sw[i] ||
       s[i].bytes!=packed_bytes(j->sc[i],j->sh[i],j->sw[i]) || !span(s[i].data,s[i].bytes) ||
       overlap(out,bytes,s[i].data,s[i].bytes)) return -1;
    /* All generated maps and lookup tables are immutable, selected-model data.
     * No operation below can fail after the first output write. */
    /* Dense Add has no channel or X padding, and its loop writes every byte. */
    if(j->mode!=ZN_ADD || !j->c || !j->h || !j->w || (j->c&3u) ||
       (j->w&15u) || j->bytes!=packed_bytes(j->c,j->h,j->w))
        memset(out,0,bytes);
    op=&operands[j->operand_first];
    if(j->mode==ZN_HEADS) {
        for(i=0;i<j->operands;i++) for(c=0;c<op[i].c;c++) {
            const Map *m=&maps[op[i].first+c];
            const ZnNativeViewSourceV1 *v=&s[m->source];
            const uint8_t *lut=unary+(size_t)m->lut*256u;
            const size_t groups=((v->channels-m->channel/32u*32u<32u?
                v->channels-m->channel/32u*32u:32u)+3u)/4u;
            const size_t block_stride=groups*64u;
            const size_t row_stride=((v->width+15u)/16u)*block_stride;
            const uint8_t *row=v->data+offset(v->channels,v->height,v->width,m->channel,0,0);
            /* Frozen HEADS maps all have dh=dw=1. Preserve general behavior
             * through the original sampler if future generated maps differ. */
            if(m->dh!=1u || m->dw!=1u) {
                for(y=0;y<op[i].h;y++) for(x=0;x<op[i].w;x++)
                    out[cursor++]=sample(&op[i],s,c,y,x);
                continue;
            }
            for(y=0;y<op[i].h;y++) {
                const uint8_t *src=row;
                for(x=0;x<op[i].w;x+=16u) {
                    unsigned k,n=op[i].w-x<16u?op[i].w-x:16u;
                    for(k=0;k<n;k++) out[cursor++]=lut[src[k]^128u];
                    if(x+16u<op[i].w) src+=block_stride;
                }
                if(y+1u<op[i].h) row+=row_stride;
            }
        }
    } else if(j->mode==ZN_ADD) {
        const uint8_t *table=operation_tables+j->table_offset;
        for(c=0;c<j->c;c++) {
            const Map *ma=&maps[op[0].first+c], *mb=&maps[op[1].first+c];
            const ZnNativeViewSourceV1 *va=&s[ma->source], *vb=&s[mb->source];
            const size_t ga=((va->channels-ma->channel/32u*32u<32u?
                va->channels-ma->channel/32u*32u:32u)+3u)/4u;
            const size_t gb=((vb->channels-mb->channel/32u*32u<32u?
                vb->channels-mb->channel/32u*32u:32u)+3u)/4u;
            const size_t go=((j->c-c/32u*32u<32u?j->c-c/32u*32u:32u)+3u)/4u;
            const size_t ra=((va->width+15u)/16u)*ga*64u;
            const size_t rb=((vb->width+15u)/16u)*gb*64u;
            const size_t ro=((j->w+15u)/16u)*go*64u;
            const uint8_t *arow=va->data+offset(va->channels,va->height,va->width,ma->channel,0,0);
            const uint8_t *brow=vb->data+offset(vb->channels,vb->height,vb->width,mb->channel,0,0);
            uint8_t *orow=out+offset(j->c,j->h,j->w,c,0,0);
            /* All selected-model ADD maps have dh=dw=1. */
            if(ma->dh!=1u || ma->dw!=1u || mb->dh!=1u || mb->dw!=1u) {
                for(y=0;y<j->h;y++) for(x=0;x<j->w;x++) {
                    unsigned a=sample_raw(op,s,c,y,x),b=sample_raw(op+1,s,c,y,x);
                    out[offset(j->c,j->h,j->w,c,y,x)]=table[(a<<8)+b];
                }
                continue;
            }
            for(y=0;y<j->h;y++) {
                const uint8_t *ap=arow,*bp=brow;
                uint8_t *dp=orow;
                for(x=0;x<j->w;x+=16u) {
                    unsigned k,n=j->w-x<16u?j->w-x:16u;
                    for(k=0;k<n;k++) {
                        unsigned a=ap[k],b=bp[k];
                        dp[k]=table[(a<<8)+b];
                    }
                    if(x+16u<j->w) { ap+=ga*64u; bp+=gb*64u; dp+=go*64u; }
                }
                if(y+1u<j->h) { arow+=ra; brow+=rb; orow+=ro; }
            }
        }
    } else for(c=0;c<j->c;c++) for(y=0;y<j->h;y++) for(x=0;x<j->w;x++) {
        uint8_t value;
        {
            int best=-128;unsigned ky,kx;
            for(ky=0;ky<j->kernel;ky++) for(kx=0;kx<j->kernel;kx++) {
                int iy=(int)(y*j->stride+ky)-(int)j->pad,ix=(int)(x*j->stride+kx)-(int)j->pad;
                if(iy>=0 && ix>=0 && iy<op->h && ix<op->w) {
                    unsigned raw=sample(op,s,c,(unsigned)iy,(unsigned)ix);
                    int signed_value=(int)(raw^128u)-128;
                    if(signed_value>best) best=signed_value;
                }
            }
            value=operation_tables[j->table_offset+(unsigned)(best+128)];
        }
        out[offset(j->c,j->h,j->w,c,y,x)]=value;
    }
    return 0;
}
